function collectUnavailableAgentSkills(e){return e.skills.filter(e=>!e.eligible&&!e.disabled&&!e.blockedByAllowlist&&!e.blockedByAgentFilter&&!e.platformIncompatible)}function formatMissingSkillSummary(e){return[[`bins`,e.missing.bins],[`any bins`,e.missing.anyBins],[`env`,e.missing.env],[`config`,e.missing.config],[`os`,e.missing.os]].filter(([,e])=>e.length>0).map(([e,t])=>`${e}: ${t.join(`, `)}`).join(`; `)||`unknown requirement`}function disableUnavailableSkillsInConfig(e,t){if(t.length===0)return e;const n={...e.skills?.entries};for(const e of t)n[e.skillKey]={...n[e.skillKey],enabled:false};return{...e,skills:{...e.skills,entries:n}}}export{disableUnavailableSkillsInConfig as n,formatMissingSkillSummary as r,collectUnavailableAgentSkills as t};